# Completa la línea marcada y compruébala con py check.
def matriz_confusion(etiquetas, predicciones):
    m = {"vp": 0, "fp": 0, "vn": 0, "fn": 0}
    for e, p in zip(etiquetas, predicciones):
        if e == 1 and p == 1:
            m["vp"] += 1
        elif e == 0 and p == 1:
            m["fp"] += 1
        elif e == 0 and p == 0:
            m["vn"] += 1
        # ← añade aquí el último caso: un ataque que se escapa
    return m

print(matriz_confusion([1, 0, 1, 0], [1, 1, 0, 0]))
